# Generates orphan_synth/orphan_cutoff_rom.v: 512-step log cutoff (40 Hz .. 8 kHz) -> Chamberlin SVF f coefficient (Q16).
import math

FS = 48828.125
N = 512
lines = []
for i in range(N):
    fc = 40.0 * (8000.0 / 40.0) ** (i / (N - 1))
    f = min(0.95, 2 * math.sin(math.pi * fc / FS))
    lines.append("            9'd%d: q <= 16'd%d;" % (i, int(f * 65535)))
v = """`timescale 1ns / 1ps
// Orphan Synth cutoff table (generated by gen_cutoff_rom.py): log cutoff index (40 Hz .. 8 kHz, 512 steps)
// -> state-variable filter coefficient f = 2 sin(pi fc / fs), Q16, capped at 0.95. 1 clock latency.
module orphan_cutoff_rom (
    input  wire        clk,
    input  wire [8:0]  a,
    output reg  [15:0] q = 16'd0
);
    always @(posedge clk) begin
        case (a)
%s
            default: q <= 16'd0;
        endcase
    end
endmodule
""" % '\n'.join(lines)
open('orphan_synth/orphan_cutoff_rom.v', 'w', newline='\n').write(v)
print('wrote', N, 'entries')
